                                localStorage.removeItem('__test__');
                                return true;
                            } catch (e) {
                                return false;
                            }
                        }
                    },
                    {
                        name: '数据读写测试',
                        description: '验证LocalStorage数据读写功能',
                        test: () => {
                            try {
                                const key = 'memo_2024-01-01';
                                const value = '测试内容';
                                localStorage.setItem(key, value);
                                const stored = localStorage.getItem(key);
                                localStorage.removeItem(key);
                                return stored === value;
                            } catch (e) {
                                return false;
                            }
                        }
                    }
                ]
            }
        ];

        // 运行测试
        function runTests() {
            const results = {
                total: 0,
                passed: 0,
                failed: 0,
                details: []
            };

            const container = document.getElementById('testResults');
            container.innerHTML = '';

            testCases.forEach(category => {
                const categoryDiv = document.createElement('div');
                categoryDiv.className = 'section';
                categoryDiv.innerHTML = '<h3>' + category.category + '</h3>';

                category.tests.forEach(test => {
                    results.total++;
                    const passed = test.test();
                    if (passed) results.passed++;
                    else results.failed++;

                    const testDiv = document.createElement('div');
                    testDiv.className = 'test-item ' + (passed ? 'pass' : 'fail');
                    testDiv.innerHTML = 
                        '<h3>' + test.name + '</h3>' +
                        '<p>' + test.description + '</p>' +
                        '<span class="status ' + (passed ? 'pass' : 'fail') + '">' + 
                        (passed ? '✅ 通过' : '❌ 失败') + '</span>';

                    categoryDiv.appendChild(testDiv);

                    results.details.push({
                        category: category.category,
                        name: test.name,
                        passed: passed
                    });
                });

                container.appendChild(categoryDiv);
            });

            // 更新统计信息
            document.getElementById('totalTests').textContent = results.total;
            document.getElementById('passedTests').textContent = results.passed;
            document.getElementById('failedTests').textContent = results.failed;
            document.getElementById('passRate').textContent = 
                Math.round((results.passed / results.total) * 100) + '%';

            // 更新结论
            const conclusion = document.getElementById('conclusion');
            if (results.failed === 0) {
                conclusion.innerHTML = '🎉 <strong>所有测试通过！</strong> 项目功能验证成功，可以正常使用。';
            } else {
                conclusion.innerHTML = '⚠️ <strong>有 ' + results.failed + ' 个测试失败</strong>，请检查相关功能。';
            }

            return results;
        }

        // 页面加载完成后运行测试
        window.onload = runTests;
    </script>
